  const about = col(card(col(`<div style="display:flex;align-items:center"><div style="flex:1;font-size:14.5px;font-weight:700">Featured works</div><span style="font-size:13.5px;font-weight:700;color:var(--accent-fg);display:flex;gap:4px;align-items:center">${I('Plus', 15, 'currentColor', 2.4)}Add</span></div><div style="display:flex;gap:8px">${['w1', 'w3', 'w6'].map((s) => `<div style="flex:1;height:72px;border-radius:12px;background:${img(s)}"></div>`).join('')}</div>`, 10), { pad: '14px 16px' }) + card(col(`<div style="font-size:14px;line-height:1.5;color:var(--text-secondary)">I shoot brand films for African founders, then teach the business side: pricing, pitching and keeping clients.</div>` + [['MapPin', 'Lagos, Nigeria'], ['Calendar', 'On Who Made This? since March 2025'], ['Globe', 'lennoxfilms.com']].map(([ic, t]) => rowx(I(ic, 15, 'var(--text-muted)') + `<span style="font-size:13.5px">${t}</span>`, 8)).join(''), 9), { pad: '14px 16px' }) + card(col(`<div style="font-size:14.5px;font-weight:700">Experience</div>` + role('Founder, director', 'Lennox Films', '2021 to now') + role('Brand strategist', 'Noah Agency, Lagos', '2018 to 2021', true), 12), { pad: '14px 16px' }) + card(col(`<div style="font-size:14.5px;font-weight:700">Skills and expertise</div><div style="display:flex;flex-wrap:wrap;gap:6px">${['Brand film', 'Colour grading', 'Pricing', 'Pitch decks'].map((t) => `<span style="height:30px;padding:0 12px;border-radius:999px;box-shadow:inset 0 0 0 1px var(--border-strong);font-size:13px;font-weight:600;display:grid;place-items:center">${t}</span>`).join('')}</div>`, 10), { pad: '14px 16px' }), 10);

