  const work = (s, t, c, w = 150) => `<div style="width:${w}px;flex-shrink:0;display:flex;flex-direction:column;gap:7px"><div style="height:${Math.round(w * 0.72)}px;border-radius:16px;background:${img(s)}"></div><div style="font-size:14px;font-weight:600;line-height:1.25">${t}</div><div style="font-size:12.5px;color:var(--text-muted)">${c}</div></div>`;
